<?php
declare(strict_types=1);
require_once __DIR__.'/includes/functions.php';
$lang=lang();
$projects=db()->query('SELECT * FROM projects ORDER BY (status="active") DESC,id DESC')->fetchAll();
$pageTitle='Projects';require __DIR__.'/includes/header.php';
?>
<section class="section"><div class="container"><div class="public-page-heading"><p class="eyebrow"><?=e(setting('projects_eyebrow',"OUR WORK"))?></p><h1 class="section-title"><?=e(setting('projects_title','Projects built with the community.'))?></h1><p class="copy"><?=e(setting('projects_intro',"Explore ATACJL's cultural, youth and recreational initiatives. Each project starts with people, ideas and a shared desire to take part."))?></p></div>
<?php if($projects):?><div class="grid-3 project-list-grid"><?php foreach($projects as $p):?><article class="card"><div class="card-media"><?php if($p['featured_image']):?><img loading="lazy" src="<?=e($p['featured_image'])?>" alt="<?=e(localTitle($p,$lang))?>"><?php else:?><div class="media-placeholder" aria-hidden="true"><span><?=e(mb_substr(localTitle($p,$lang),0,1))?></span></div><?php endif;?></div><div class="card-body"><div class="meta-row"><span class="tag"><?=e($p['category'])?></span><span class="status-chip <?=($p['status']==='completed')?'status-draft':'status-active'?>"><?=e(ucfirst($p['status']))?></span></div><h2 class="content-card-title"><?=e(localTitle($p,$lang))?></h2><p><?=e(mb_strimwidth(strip_tags(localDescription($p,$lang)),0,180,'…'))?></p><?php if($p['start_date']):?><p class="muted"><?=e(setting('projects_started_label','Started'))?> <?=e(date('M Y',strtotime($p['start_date'])))?><?php if($p['end_date']):?> · <?=e(date('M Y',strtotime($p['end_date'])))?><?php endif;?></p><?php endif;?><a class="text-link" href="project-detail.php?id=<?=$p['id']?>"><?=e(setting('projects_card_link','Explore project'))?> <span aria-hidden="true">→</span></a></div></article><?php endforeach;?></div><?php else:?><div class="empty-state"><span class="empty-icon">✳</span><h2><?=e(setting('projects_empty_title','Projects are on the way'))?></h2><p><?=e(setting('projects_empty_text',"ATACJL's project stories will appear here as they are published."))?></p><a class="btn ghost" href="<?=APP_URL?>/contact.php"><?=e(setting('projects_empty_link','Contact the association'))?></a></div><?php endif;?></div></section>
<?php require __DIR__.'/includes/footer.php'; ?>
